/** Vitest: ar/en string tables for manual topic key coverage. */
export { translations as guideTranslations };

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

function readSaved<T extends string>(key: string, allowed: readonly T[], fallback: T): T {
  try {
    const v = localStorage.getItem(key);
    if (v && (allowed as readonly string[]).includes(v)) return v as T;
  } catch { /* private browsing / storage disabled */ }
  return fallback;
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() =>
    readSaved('app_language', ['ar', 'en'] as const, 'ar'),
  );
  const [theme, setThemeState] = useState<Theme>(() => {
    try {
      const raw = localStorage.getItem('app_theme');
      const normalized = coerceAppTheme(raw, 'erp');
      if (raw === 'odoo') localStorage.setItem('app_theme', 'erp');
      return normalized;
    } catch {
      return 'erp';
    }
  });

  const setLanguage = useCallback((lang: Language) => {
    try { localStorage.setItem('app_language', lang); } catch { /* ignore */ }
    setLanguageState(lang);
  }, []);

  const setTheme = useCallback((next: Theme) => {
    const normalized = coerceAppTheme(next);
    try { localStorage.setItem('app_theme', normalized); } catch { /* ignore */ }
    setThemeState(normalized);
  }, []);

  const t = useCallback((key: string) => {
    const val = translations[language][key];
    if (val === undefined && import.meta.env.DEV) {
      console.warn(`[i18n] Missing translation key: "${key}" for language "${language}"`);
    }
    return val ?? key;
  }, [language]);

  const dir: 'rtl' | 'ltr' = language === 'ar' ? 'rtl' : 'ltr';
  const locale = displayLocale(language);

  const formatMoney = useCallback(
    (value: unknown) => formatMoneyAmount(value, NUMBER_LOCALE),
    [],
  );

  const formatNumberStable = useCallback(
    (value: number, options?: Intl.NumberFormatOptions) => formatNumber(value, options),
    [],
  );

  const contextValue = useMemo(
    () => ({ language, setLanguage, theme, setTheme, t, dir, locale, formatMoney, formatNumber: formatNumberStable }),
    [language, setLanguage, theme, setTheme, t, dir, locale, formatMoney, formatNumberStable],
  );

  useEffect(() => {
    document.documentElement.dir = dir;
    document.documentElement.lang = language;
    document.documentElement.classList.remove('dark', 'soft', 'erp', 'odoo');
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else if (theme === 'soft') {
      document.documentElement.classList.add('soft');
    } else if (theme === 'erp') {
      document.documentElement.classList.add('erp');
    }
  }, [language, dir, theme]);

  return (
    <LanguageContext.Provider value={contextValue}>
      <div className={cn(
        theme === 'dark' ? 'dark' : '',
        theme === 'soft' ? 'soft' : '',
        theme === 'erp' ? 'erp' : '',
      )}>
        {children}
      </div>
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
}

/**
 * Context modules must not HMR in-place — a second createContext() leaves consumers
 * on a different instance than LanguageProvider (useLanguage throws + createRoot noise).
 */
if (import.meta.hot) {
  import.meta.hot.decline();
}
